WORKER_ENV_KEYS='["NODE_VERSION","APP_URL","DB_HOST","DB_USER","DB_PASSWORD","S3_ENDPOINT","S3_REGION","S3_ACCESS_KEY","S3_SECRET_KEY","MEDIA_PUBLIC_BASE_URL","SUPABASE_URL","SUPABASE_SECRET_KEY","FIELD_ENCRYPTION_KEYS","SMTP_URL","MAIL_FROM","REDIS_URL"]'

ROOT=""
