# ---- small output helpers -------------------------------------------------
die() { printf '  %s✗ %s%s\n' "$YELLOW" "$1" "$RESET" >&2; exit 1; }
ok()  { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
bad() { printf '  %s✗%s %s\n' "$YELLOW" "$RESET" "$1"; }

# ---- persistent state (step ids and non-secret values only) --------------
state_has() { [[ -f $STATE_FILE ]] && grep -qxF -- "$1" "$STATE_FILE"; }
state_add() {
  if ! state_has "$1"; then (umask 077; printf '%s\n' "$1" >> "$STATE_FILE"); fi
  return 0
}
state_del() {
  [[ -f $STATE_FILE ]] || return 0
  local tmp; tmp=$(mktemp)
  grep -vxF -- "$1" "$STATE_FILE" > "$tmp" || true
  cat "$tmp" > "$STATE_FILE"; rm -f "$tmp"
}
state_set() {  # state_set KEY VALUE (non-secret only)
  [[ -f $STATE_FILE ]] || (umask 077; : > "$STATE_FILE")
  local tmp; tmp=$(mktemp)
  grep -v "^kv:$1=" "$STATE_FILE" > "$tmp" || true
  printf 'kv:%s=%s\n' "$1" "$2" >> "$tmp"
  cat "$tmp" > "$STATE_FILE"; rm -f "$tmp"
}
state_get() {
  [[ -f $STATE_FILE ]] || return 0
  grep "^kv:$1=" "$STATE_FILE" | tail -n1 | sed "s/^kv:$1=//" || true
}
is_done() { state_has "done:$1" || state_has "skip:$1"; }
site_origin() { local o; o=$(state_get ORIGIN); printf '%s' "${o:-$DEFAULT_ORIGIN}"; }

# begin ID "Title" "Dòng tiếng Việt": announce a stage, or skip it if already done.
begin() {
  if is_done "$1"; then
    _STAGE_INDEX=$((_STAGE_INDEX + 1)); PREV_DONE+=("$1"); return 1
  fi
  stage "$2"; note "$3"
  if (( ${#PREV_DONE[@]} )); then note "already finished earlier (skipped): ${PREV_DONE[*]}"; fi
  printf '\n'
  return 0
}
# optional_gate ID "question": returns 0 to proceed; otherwise records an on-purpose skip.
optional_gate() {
  if confirm "$2"; then return 0; fi
  state_add "skip:$1"
  SKIPPED+=("stage $1 skipped on purpose (revisit with: scripts/release-wizard.sh --reset $1)")
  return 1
}
# finish_stage ID STATUS: STATUS 0 marks the stage done; anything else leaves it open.
finish_stage() {
  if [[ $2 == 0 ]]; then
    state_add "done:$1"; ok "stage $1 done"
  else
    SKIPPED+=("stage $1 not verified (re-run the wizard to retry)"); HAS_FAILURE=1
    bad "stage $1 left open"
  fi
  pause "Press Enter for the next stage"
  return 0
}

# ---- dotenv + hashing helpers (values are never printed) ------------------
# env_val FILE KEY: value of KEY (quotes and a trailing " # comment" stripped).
env_val() {
  local file=$1 key=$2 line v
  [[ -f $file ]] || return 1
  line=$(grep -E "^${key}=" "$file" | tail -n1) || return 1
  v=${line#*=}
  if [[ $v == \"* ]]; then v=${v#\"}; v=${v%%\"*}
  elif [[ $v == \'* ]]; then v=${v#\'}; v=${v%%\'*}
  else v=$(printf '%s' "$v" | sed -E 's/[[:space:]]+#.*$//; s/[[:space:]]+$//'); fi
  printf '%s' "$v"
}
envv() { env_val "$ENV_FILE" "$1"; }
sha8() {
  if command -v shasum >/dev/null 2>&1; then printf '%s' "$1" | shasum -a 256 | cut -c1-8
  else printf '%s' "$1" | sha256sum | cut -c1-8; fi
}
urlenc() { printf '%s' "$1" | jq -sRr '@uri'; }

# ---- HTTP helper: tokens go through curl's config on a pipe, bodies through stdin ----
# http KIND METHOD URL [JSON]: sets HTTP_CODE and HTTP_BODY; success = 2xx.
http() {
  local kind=$1 method=$2 url=$3 data=${4-} token raw rc=0
  case $kind in
    vercel) token=$VERCEL_TOKEN_VAL ;;
    render) token=$RENDER_TOKEN_VAL ;;
    *) return 2 ;;
  esac
  if [[ -n $data ]]; then
    raw=$(printf '%s' "$data" | curl -sS -m 90 -X "$method" -K <(printf 'header = "Authorization: Bearer %s"\n' "$token") \
      -H 'Content-Type: application/json' --data-binary @- -w $'\n%{http_code}' "$url") || rc=$?
  else
    raw=$(curl -sS -m 90 -X "$method" -K <(printf 'header = "Authorization: Bearer %s"\n' "$token") \
      -w $'\n%{http_code}' "$url") || rc=$?
  fi
  if (( rc )); then HTTP_CODE=000; HTTP_BODY=""; return 1; fi
  HTTP_CODE=${raw##*$'\n'}
  HTTP_BODY=${raw%$'\n'*}
  [[ $HTTP_CODE == 2* ]]
}
api_error() { jq -r '.error.message // .error.code // .message // .error // empty' <<<"$HTTP_BODY" 2>/dev/null | head -n3; }
show_api_error() { bad "HTTP $HTTP_CODE: $(api_error)"; }

load_tokens() {
  local f
  VERCEL_TOKEN_VAL="${VERCEL_TOKEN:-}"
  if [[ -z $VERCEL_TOKEN_VAL ]]; then
    for f in "$HOME/Library/Application Support/com.vercel.cli/auth.json" \
             "$HOME/.local/share/com.vercel.cli/auth.json" "$HOME/.config/com.vercel.cli/auth.json"; do
      if [[ -f $f ]]; then VERCEL_TOKEN_VAL=$(jq -r '.token // empty' "$f"); break; fi
    done
  fi
  RENDER_TOKEN_VAL="${RENDER_API_KEY:-}"
  if [[ -z $RENDER_TOKEN_VAL && -f $HOME/.render/cli.yaml ]]; then
    RENDER_TOKEN_VAL=$(awk '/^api:/{f=1;next} f&&/^[[:space:]]+key:/{print $2;exit}' "$HOME/.render/cli.yaml")
  fi
}

preflight() {
  local c su
  for c in curl jq git node; do
    command -v "$c" >/dev/null 2>&1 || die "missing required tool: $c"
  done
  command -v shasum >/dev/null 2>&1 || command -v sha256sum >/dev/null 2>&1 || die "missing shasum/sha256sum"
  [[ -f $ENV_FILE ]] || die ".env not found at $ENV_FILE (run from the checkout that holds your .env, or set ENV_FILE=/path/to/.env)"
  load_tokens
  [[ -n $VERCEL_TOKEN_VAL ]] || die "No Vercel token. Run: npx vercel login   (or export VERCEL_TOKEN=...)"
  [[ -n $RENDER_TOKEN_VAL ]] || die "No Render token. Run: render login   (or export RENDER_API_KEY=... from https://dashboard.render.com/u/settings#api-keys)"
  http vercel GET "$VERCEL_API/v9/projects/$VERCEL_PROJECT?slug=$VERCEL_SLUG" \
    || die "Vercel API rejected the token (HTTP $HTTP_CODE). Run: npx vercel login"
  VERCEL_TEAM_ID=$(jq -r '.accountId // empty' <<<"$HTTP_BODY")
  http render GET "$RENDER_API/services/$RENDER_SERVICE_ID" \
    || die "Render API rejected the token (HTTP $HTTP_CODE). Run: render login   (or set RENDER_API_KEY)"
  su=$(envv SUPABASE_URL || true)
  SUPABASE_REF=$(printf '%s' "$su" | sed -nE 's#^https://([a-z0-9]+)\.supabase\.co.*#\1#p')
  return 0
}

# ---- Render helpers --------------------------------------------------------
render_env_get() {  # render_env_get KEY [SERVICE_ID]: prints the value (capture it, never echo)
  http render GET "$RENDER_API/services/${2:-$RENDER_SERVICE_ID}/env-vars?limit=100" || return 1
  jq -r --arg k "$1" '.[] | select(.envVar.key == $k) | .envVar.value // empty' <<<"$HTTP_BODY"
}
render_env_set() {  # render_env_set KEY VALUE
  local body
  body=$(jq -n --arg v "$2" '{value: $v}')
  if http render PUT "$RENDER_API/services/$RENDER_SERVICE_ID/env-vars/$1" "$body"; then
    ok "Render: set $1"; return 0
  fi
  bad "Render: could not set $1"; show_api_error; return 1
}
# render_wait SERVICE_ID DEPLOY_ID: poll until live (0) or failed/timeout (1).
render_wait() {
  local sid=$1 did=$2 i status last=""
  for ((i = 0; i < 100; i++)); do
    if http render GET "$RENDER_API/services/$sid/deploys/$did"; then
      status=$(jq -r '.status // "unknown"' <<<"$HTTP_BODY")
      if [[ $status != "$last" ]]; then note "deploy $did: $status"; last=$status; fi
      case $status in
        live) return 0 ;;
        build_failed|update_failed|pre_deploy_failed|canceled|deactivated) return 1 ;;
      esac
    fi
    sleep 10
  done
  return 1
}
wait_url_ok() {  # wait_url_ok URL [tries]: succeed when the URL answers 2xx
  local i
  for ((i = 0; i < ${2:-12}; i++)); do
    if curl -fsS -m 30 -o /dev/null "$1" 2>/dev/null; then return 0; fi
    sleep 10
  done
  return 1
}
# render_redeploy: trigger a deploy of vcraft-api, wait for live, then check /health.
render_redeploy() {
  local did
  if ! http render POST "$RENDER_API/services/$RENDER_SERVICE_ID/deploys" '{"clearCache":"do_not_clear"}'; then
    bad "Render: could not trigger a deploy"; show_api_error; return 1
  fi
  did=$(jq -r '.id // .deploy.id // empty' <<<"$HTTP_BODY")
  if [[ -z $did ]] && http render GET "$RENDER_API/services/$RENDER_SERVICE_ID/deploys?limit=1"; then
    did=$(jq -r '.[0].deploy.id // empty' <<<"$HTTP_BODY")   # 202 "queued" answers carry no id
  fi
  [[ -n $did ]] || { bad "Render returned no deploy id"; return 1; }
  note "waiting for the Render build (typically 4-8 minutes on the free plan)..."
  render_wait "$RENDER_SERVICE_ID" "$did" || { bad "Render deploy did not go live: open https://dashboard.render.com/web/$RENDER_SERVICE_ID/events"; return 1; }
  if wait_url_ok "$API_ORIGIN/api/v1/health" 12; then ok "API health: $API_ORIGIN/api/v1/health"; return 0; fi
  bad "API health check failed after deploy"; return 1
}

# ---- Vercel helpers --------------------------------------------------------
vercel_env_set() {  # vercel_env_set KEY VALUE (production + preview, plain)
  local body
  body=$(jq -n --arg k "$1" --arg v "$2" '{key: $k, value: $v, type: "plain", target: ["production", "preview"]}')
  if http vercel POST "$VERCEL_API/v10/projects/$VERCEL_PROJECT/env?slug=$VERCEL_SLUG&upsert=true" "$body"; then
    ok "Vercel: set $1 (production + preview)"; return 0
  fi
  bad "Vercel: could not set $1"; show_api_error; return 1
}
# deploy_web: build origin/main on Vercel production. Works with or without the Git link, always uses the
# project's current env vars (NEXT_PUBLIC_* are baked at build time, so every env change needs this).
deploy_web() {
  local tmp sha rc=0
  git -C "$ROOT" fetch origin main --quiet || { bad "git fetch origin main failed"; return 1; }
  sha=$(git -C "$ROOT" rev-parse --short origin/main)
  tmp=$(mktemp -d)
  git -C "$ROOT" archive origin/main | tar -x -C "$tmp" || { rm -rf "$tmp"; bad "git archive failed"; return 1; }
  mkdir -p "$tmp/.vercel"
  jq -n --arg o "$VERCEL_TEAM_ID" --arg p "$VERCEL_PROJECT_ID" '{orgId: $o, projectId: $p}' > "$tmp/.vercel/project.json"
  note "deploying origin/main @ $sha with the Vercel CLI (a few minutes)..."
  (cd "$tmp" && npx --yes vercel deploy --prod --yes --scope "$VERCEL_SLUG") || rc=$?
  rm -rf "$tmp"
  if (( rc )); then bad "vercel deploy failed (exit $rc)"; return 1; fi
  ok "Vercel production deploy finished"
}

# ---- S3 probe: a real ListObjectsV2 against both buckets ------------------
# s3_probe ACCESS_KEY SECRET_KEY: 0 when both buckets answer. Keys travel via the environment of a subshell.
s3_probe() {
  local ak=$1 sk=$2 rc=0 out
  out=$(
    S3_ACCESS_KEY=$ak; S3_SECRET_KEY=$sk
    S3_ENDPOINT=$(envv S3_ENDPOINT); S3_REGION=$(envv S3_REGION)
    S3_BUCKET_PUBLIC=$(envv S3_BUCKET_PUBLIC || true); S3_BUCKET_PRIVATE=$(envv S3_BUCKET_PRIVATE || true)
    : "${S3_BUCKET_PUBLIC:=vcraft-media}" "${S3_BUCKET_PRIVATE:=vcraft-private}"
    export S3_ACCESS_KEY S3_SECRET_KEY S3_ENDPOINT S3_REGION S3_BUCKET_PUBLIC S3_BUCKET_PRIVATE
    node --input-type=module -e "$S3_PROBE_JS" 2>&1
  ) || rc=$?
  printf '%s\n' "$out" | sed 's/^/    /'
  return "$rc"
}

# ===========================================================================
# Stage 1: Vercel <-> GitHub
# ===========================================================================
vercel_link_ok() {  # reads the project from Vercel; 0 when linked to REPO_SLUG
  http vercel GET "$VERCEL_API/v9/projects/$VERCEL_PROJECT?slug=$VERCEL_SLUG" || return 1
  jq -e --arg want "$(printf '%s' "$REPO_SLUG" | tr '[:upper:]' '[:lower:]')" '
    .link != null and .link.type == "github" and
    ( (if ((.link.repo // "") | contains("/")) then .link.repo else ((.link.org // "") + "/" + (.link.repo // "")) end)
      | ascii_downcase) == $want' <<<"$HTTP_BODY" >/dev/null
}
github_connected() {  # the Vercel account has a GitHub login connection with a namespace for the repo owner
  http vercel GET "$VERCEL_API/v1/integrations/git-namespaces?provider=github" || return 1
  jq -e --arg o "$(printf '%s' "${REPO_SLUG%%/*}" | tr '[:upper:]' '[:lower:]')" '
    (if type == "array" then . else [] end)
    | map(select(((.slug // .name // "") | ascii_downcase) == $o)) | length > 0' <<<"$HTTP_BODY" >/dev/null
}

stage_vercel_github() {
  begin s1 "Connect Vercel to GitHub" "Nối Vercel với GitHub để merge vào main tự deploy, PR có bản preview." || return 0
  say "Why: today the web is deployed by hand with the CLI. Linking the repo gives auto-deploy on"
  say "merge to main and preview deployments for pull requests (GH#39 acceptance)."
  printf '\n'
  local status=1 tries=0
  if vercel_link_ok; then
    ok "project $VERCEL_PROJECT is already linked to $REPO_SLUG"
  else
    if github_connected; then
      ok "Vercel account has a GitHub connection for ${REPO_SLUG%%/*}"
    else
      warn "Vercel account has no GitHub connection for ${REPO_SLUG%%/*} yet."
      open_url "https://vercel.com/account/authentication"
      step "Vercel avatar → Settings → Authentication → Login Connections → GitHub → Connect."
      step "Sign in to GitHub as ${REPO_SLUG%%/*} and approve."
      open_url "https://github.com/apps/vercel"
      step "Click Configure → choose ${REPO_SLUG%%/*} → Repository access:"
      step "pick 'Only select repositories' and tick ${REPO_SLUG##*/} (or 'All repositories') → Save."
      pause "Press Enter when both are done"
      if github_connected; then ok "GitHub connection detected"
      else warn "still not detected; the link attempt below will tell us the truth"; fi
    fi
    while :; do
      printf '\n'; say "Linking $VERCEL_PROJECT → $REPO_SLUG via the Vercel API..."
      if http vercel POST "$VERCEL_API/v9/projects/$VERCEL_PROJECT/link?slug=$VERCEL_SLUG" \
           "$(jq -n --arg r "$REPO_SLUG" '{type: "github", repo: $r}')"; then
        ok "link request accepted"; break
      fi
      show_api_error
      tries=$((tries + 1))
      if (( tries >= 3 )); then warn "giving up for now"; break; fi
      confirm "Retry the link?" || break
    done
  fi
  say "Setting the production branch to main..."
  if http vercel PATCH "$VERCEL_API/v9/projects/$VERCEL_PROJECT/branch?slug=$VERCEL_SLUG" '{"branch":"main"}'; then
    ok "production branch request accepted"
  else
    show_api_error
    warn "If it is not main: Vercel → project → Settings → Environments → Production → Branch Tracking → main."
  fi
  printf '\n'; say "Verifying..."
  if vercel_link_ok; then
    ok "link.repo = $(jq -r '(.link.org // "") as $o | .link.repo | if contains("/") then . else $o + "/" + . end' <<<"$HTTP_BODY")"
    local pb; pb=$(jq -r '.link.productionBranch // empty' <<<"$HTTP_BODY")
    if [[ $pb == main ]]; then ok "production branch = main"; status=0
    else bad "production branch is '${pb:-unknown}', expected main"; open_url "https://vercel.com/$VERCEL_SLUG/$VERCEL_PROJECT/settings/environments"; confirm "Fixed it by hand?" && status=0; fi
  else
    bad "project is not linked to $REPO_SLUG"
  fi
  finish_stage s1 "$status"
  return 0
}

# ===========================================================================
# Stage 2 (optional): Render paid plans
# ===========================================================================
render_find_worker() {  # prints the id of the service named vcraft-worker, if any
  http render GET "$RENDER_API/services?name=vcraft-worker&limit=5" || return 1
  jq -r '[.[].service | select(.name == "vcraft-worker") | .id][0] // empty' <<<"$HTTP_BODY"
}
render_upgrade_all() {
  local envs body wid did
  say "1/4 reading vcraft-api env vars (values stay in memory)..."
  http render GET "$RENDER_API/services/$RENDER_SERVICE_ID/env-vars?limit=100" || { show_api_error; return 1; }
  envs=$HTTP_BODY
  say "2/4 upgrading vcraft-api to starter and restoring the Blueprint commands..."
  body=$(jq -n --arg b "$API_BUILD_CMD" --arg s "$API_START_CMD" --arg p "$PRE_DEPLOY_CMD" \
    '{serviceDetails: {plan: "starter", preDeployCommand: $p, envSpecificDetails: {buildCommand: $b, startCommand: $s}}}')
  http render PATCH "$RENDER_API/services/$RENDER_SERVICE_ID" "$body" || { show_api_error; return 1; }
  ok "vcraft-api: plan starter + build/start/preDeploy commands"
  say "3/4 creating the background worker vcraft-worker (starter, frankfurt)..."
  wid=$(render_find_worker || true)
  if [[ -n $wid ]]; then
    ok "vcraft-worker already exists ($wid)"
  else
    body=$(printf '%s' "$envs" | jq --arg owner "$RENDER_OWNER_ID" --arg repo "https://github.com/$REPO_SLUG" \
      --arg b "$WORKER_BUILD_CMD" --arg s "$WORKER_START_CMD" --argjson keys "$WORKER_ENV_KEYS" '
      {type: "background_worker", name: "vcraft-worker", ownerId: $owner, repo: $repo, branch: "main",
       autoDeployTrigger: "checksPass",
       envVars: [.[].envVar | select(.key | IN($keys[])) | {key: .key, value: .value}],
       serviceDetails: {runtime: "node", plan: "starter", region: "frankfurt", numInstances: 1,
                        envSpecificDetails: {buildCommand: $b, startCommand: $s}}}')
    http render POST "$RENDER_API/services" "$body" || { show_api_error; return 1; }
    wid=$(jq -r '.service.id // .id // empty' <<<"$HTTP_BODY")
    [[ -n $wid ]] || { bad "Render returned no service id"; return 1; }
    ok "created vcraft-worker ($wid)"
    if http render POST "$RENDER_API/env-groups/$RENDER_ENV_GROUP_ID/services/$wid"; then
      ok "linked env group vcraft-shared to the worker"
    else
      show_api_error; warn "Link it by hand: Render → Env Groups → vcraft-shared → Linked services → add vcraft-worker."
    fi
  fi
  say "4/4 redeploying vcraft-api with the new commands (migrations now run as pre-deploy)..."
  render_redeploy || return 1
  did=""; http render GET "$RENDER_API/services/$wid/deploys?limit=1" && did=$(jq -r '.[0].deploy.id // empty' <<<"$HTTP_BODY")
  if [[ -n $did ]]; then
    note "waiting for the worker's first deploy..."
    if render_wait "$wid" "$did"; then
      ok "vcraft-worker is live (its log should show: queues ready: media, mail, outbox)"
    else
      warn "worker deploy not live yet: check https://dashboard.render.com/worker/$wid"
    fi
  fi
  return 0
}
stage_render_paid() {
  begin s2 "Render paid plan (optional)" "Tùy chọn: nâng Render lên gói trả phí để API không ngủ và có worker riêng." || return 0
  say "Free plan today: API sleeps after 15 min (pg_cron pings it every 10 min to keep it awake), the"
  say "worker runs inside the API container, 750 instance-hours/month, no pre-deploy migrations."
  say "Paid: vcraft-api on starter + a separate starter vcraft-worker (roughly 7 USD/month each; check"
  say "the Render pricing page), migrations as pre-deploy, no keep-alive hack. Skip it if budget is tight."
  printf '\n'
  optional_gate s2 "Move to paid plans now?" || return 0
  local status=1 wid=""
  open_url "https://dashboard.render.com/billing"
  step "Billing → Payment methods → Add a card → Save."
  pause "Press Enter once the card is saved"
  if confirm "Upgrade vcraft-api, restore render.yaml commands and create vcraft-worker via the API?"; then
    render_upgrade_all || {
      warn "The API route failed. Manual route (Render dashboard):"
      step "vcraft-api → Settings → Instance Type → Starter; Build/Start commands as in render.yaml; add Pre-Deploy command."
      step "New → Background Worker → repo $REPO_SLUG, branch main, region Frankfurt, Starter; copy the env vars from vcraft-api."
      pause "Press Enter after doing it by hand"
    }
  else
    pause "Do the upgrade by hand (docs/deploy.md, section 'Moving back to the starter Blueprint'), then press Enter"
  fi
  printf '\n'; say "Verifying..."
  http render GET "$RENDER_API/services/$RENDER_SERVICE_ID" || true
  if [[ $(jq -r '.serviceDetails.plan // empty' <<<"$HTTP_BODY") == starter ]]; then ok "vcraft-api plan = starter"; status=0; else bad "vcraft-api plan is not starter"; fi
  wid=$(render_find_worker || true)
  if [[ -n $wid ]]; then ok "vcraft-worker exists ($wid)"; else bad "vcraft-worker not found"; status=1; fi
  finish_stage s2 "$status"
  return 0
}

# ===========================================================================
# Stage 3 (optional): custom domain
# ===========================================================================
stage_domain() {
  begin s3 "Custom domain (optional)" "Tùy chọn: gắn tên miền riêng (ví dụ vcraft.vn) cho web." || return 0
  say "Why: a branded domain on the QR labels. WARNING: printed QR codes encode this domain, so pick"
  say "the final one BEFORE printing; changing it later invalidates every printed label."
  printf '\n'
  optional_gate s3 "Attach a custom domain now?" || return 0
  local d apex_ip cname ver status=1 i origin_new
  while :; do
    ask WIZ_DOMAIN "Domain (e.g. vcraft.vn or www.vcraft.vn, no https://):"
    WIZ_DOMAIN=$(printf '%s' "$WIZ_DOMAIN" | tr '[:upper:]' '[:lower:]')
    if [[ $WIZ_DOMAIN =~ ^([a-z0-9-]+\.)+[a-z]{2,}$ ]]; then break; fi
    warn "that does not look like a hostname"
  done
  d=$WIZ_DOMAIN
  say "Adding $d to the Vercel project..."
  if http vercel POST "$VERCEL_API/v10/projects/$VERCEL_PROJECT/domains?slug=$VERCEL_SLUG" "$(jq -n --arg n "$d" '{name: $n}')"; then
    ok "domain added"
  elif [[ $(jq -r '.error.code // empty' <<<"$HTTP_BODY") == domain_already_in_use || $HTTP_CODE == 409 ]]; then
    note "domain already attached: continuing"
  else
    show_api_error; warn "Add it by hand: Vercel → project → Settings → Domains."; pause "Press Enter when added"
  fi
  http vercel GET "$VERCEL_API/v6/domains/$d/config?slug=$VERCEL_SLUG" || true
  apex_ip=$(jq -r '.recommendedIPv4[0].value[0]? // "76.76.21.21"' <<<"$HTTP_BODY" 2>/dev/null || echo 76.76.21.21)
  cname=$(jq -r '.recommendedCNAME[0].value? // "cname.vercel-dns.com"' <<<"$HTTP_BODY" 2>/dev/null || echo cname.vercel-dns.com)
  printf '\n'; say "At your DNS provider create (TTL 60 seconds, so a fallback switch is fast):"
  if [[ $(printf '%s' "$d" | tr -cd '.' | wc -c | tr -d ' ') -le 1 ]]; then
    step "A      @    →  $apex_ip"
  else
    step "CNAME  ${d%%.*}  →  ${cname%.}"
  fi
  http vercel GET "$VERCEL_API/v9/projects/$VERCEL_PROJECT/domains/$d?slug=$VERCEL_SLUG" || true
  ver=$(jq -r 'select(.verified == false) | .verification[]? | "TXT  " + .domain + "  →  " + .value' <<<"$HTTP_BODY" 2>/dev/null || true)
  if [[ -n $ver ]]; then warn "Vercel also asks for an ownership record:"; printf '%s\n' "$ver" | sed 's/^/    /'; fi
  open_url "https://vercel.com/$VERCEL_SLUG/$VERCEL_PROJECT/settings/domains"
  pause "Press Enter after saving the DNS record(s)"
  for ((i = 0; i < 18; i++)); do
    http vercel GET "$VERCEL_API/v6/domains/$d/config?slug=$VERCEL_SLUG" || true
    if [[ $(jq -r '.misconfigured // true' <<<"$HTTP_BODY" 2>/dev/null) == false ]] \
       && curl -fsS -m 20 -o /dev/null "https://$d/api/v1/health" 2>/dev/null; then status=0; break; fi
    note "DNS/HTTPS not ready yet ($((i + 1))/18), waiting 20s..."; sleep 20
  done
  if (( status )); then bad "https://$d does not serve the app yet (DNS propagation or certificate issuance can take minutes)"; finish_stage s3 1; return 0; fi
  ok "https://$d serves the app (HTTPS + rewrite to the API work)"
  origin_new="https://$d"
  printf '\n'; warn "Switching the site origin to $origin_new re-bakes NEXT_PUBLIC_SITE_URL (QR labels) and redeploys both apps."
  if confirm "Switch the production origin to $origin_new now?"; then
    status=1
    if vercel_env_set NEXT_PUBLIC_SITE_URL "$origin_new" && render_env_set APP_URL "$origin_new"; then
      state_set ORIGIN "$origin_new"
      deploy_web && render_redeploy && status=0
    fi
    if (( status == 0 )); then
      local page; page=$(curl -fsS -m 30 "$origin_new/vi" 2>/dev/null || true)
      if grep -q "$d" <<<"$page"; then ok "site renders with the new origin"; fi
    fi
  else
    SKIPPED+=("custom domain $d is attached but the origin was not switched (NEXT_PUBLIC_SITE_URL, APP_URL)")
  fi
  if http vercel GET "$VERCEL_API/v10/projects/$VERCEL_PROJECT/env?slug=$VERCEL_SLUG" \
     && jq -e '[.envs[].key] | index("NEXT_PUBLIC_TURNSTILE_SITE_KEY")' <<<"$HTTP_BODY" >/dev/null 2>&1; then
    warn "Turnstile is configured: add $d to the widget's hostnames."
    open_url "https://dash.cloudflare.com/?to=/:account/turnstile"
    pause "Press Enter after adding the hostname"
  fi
  finish_stage s3 "$status"
  return 0
}

# ===========================================================================
# Stage 4: Supabase Auth URL configuration
# ===========================================================================
stage_supabase_auth() {
  begin s4 "Supabase Auth URLs" "Đặt Site URL và Redirect URLs của Supabase Auth đúng tên miền production." || return 0
  local origin pk su st=1
  origin=$(site_origin)
  say "Why: confirmation and password-reset links use Site URL; sign-in redirects must be allow-listed,"
  say "otherwise login sends people to localhost or shows 'invalid redirect'."
  printf '\n'
  if [[ -n $SUPABASE_REF ]]; then open_url "https://supabase.com/dashboard/project/$SUPABASE_REF/auth/url-configuration"
  else open_url "https://supabase.com/dashboard"; fi
  step "Authentication → URL Configuration (if the link 404s, use the sidebar)."
  step "Site URL: $origin"
  step "Redirect URLs → Add URL: $origin/**"
  step "Optional, for preview logins: https://*-$VERCEL_SLUG.vercel.app/**"
  step "Save changes."
  pause "Press Enter once saved"
  pk=$(envv SUPABASE_PUBLISHABLE_KEY || true); su=$(envv SUPABASE_URL || true)
  if [[ -n $pk && -n $su ]]; then
    local settings; settings=$(curl -fsS -m 20 -H "apikey: $pk" "$su/auth/v1/settings" 2>/dev/null || true)
    if [[ -n $settings ]]; then
      if [[ $(jq -r '.mailer_autoconfirm' <<<"$settings") == false ]]; then
        ok "email confirmation is ON: sign-ups need working email (see the SMTP stage)"
      else
        warn "email confirmation is OFF (mailer_autoconfirm=true)"
      fi
    fi
  fi
  say "Supabase does not expose Site URL through a public API, so confirm it yourself:"
  if confirm "Site URL = $origin and Redirect URL $origin/** are saved?"; then st=0; fi
  note "Optional end-to-end test (needs SMTP from the next stages): sign up with a real address on $origin,"
  note "open the confirmation mail and check the link lands on $origin, not localhost."
  finish_stage s4 "$st"
  return 0
}

# ===========================================================================
# Stage 5: SMTP (Supabase Auth + worker mail)
# ===========================================================================
stage_smtp() {
  begin s5 "SMTP for Auth and notification mail" "Cấu hình SMTP: email xác thực (Supabase) và thông báo (worker Render)." || return 0
  say "Why: Supabase's built-in mailer is rate-limited and only mails team members. The worker needs"
  say "SMTP_URL / MAIL_FROM on Render too; without them mail jobs fail."
  printf '\n'
  note "Provider: Resend (free: 3,000 mails/month, 100/day) or Brevo (free: 300/day)."
  note "Both need the sender verified. SPF/DKIM requires a domain you own: vcraft-vn.vercel.app cannot"
  note "carry DNS records, so do the custom-domain stage first, or use Brevo 'single sender' verification"
  note "(works without a domain but is more likely to land in spam)."
  open_url "https://resend.com/domains"
  step "Resend: Domains → Add Domain → create the DNS records it shows (SPF, DKIM) at your DNS → Verify."
  step "Resend: API Keys → Create (sending access). SMTP host smtp.resend.com, user 'resend', password = the API key."
  step "Brevo alternative: SMTP & API → SMTP → host smtp-relay.brevo.com, port 587, login + SMTP key shown there."
  pause "Press Enter when the sender is verified and you have host / port / user / password"
  local host port user pass from scheme st=1 out tries=0
  ask WIZ_SMTP_HOST "SMTP host (e.g. smtp.resend.com):"
  ask WIZ_SMTP_PORT "SMTP port (465 implicit TLS, 587 STARTTLS):"
  ask WIZ_SMTP_USER "SMTP user:"
  ask_secret WIZ_SMTP_PASS "SMTP password / API key (hidden):"
  ask WIZ_MAIL_FROM "MAIL_FROM (e.g. vCraft <no-reply@yourdomain.vn>):"
  host=$WIZ_SMTP_HOST; port=$WIZ_SMTP_PORT; user=$WIZ_SMTP_USER; pass=$WIZ_SMTP_PASS; from=$WIZ_MAIL_FROM
  scheme=smtp; [[ $port == 465 ]] && scheme=smtps
  WIZ_SMTP_URL="$scheme://$(urlenc "$user"):$(urlenc "$pass")@$host:$port"
  unset WIZ_SMTP_PASS pass
  printf '\n'; say "Checking the SMTP login with nodemailer (no mail is sent)..."
  while :; do
    out=$( export WIZ_SMTP_URL; node --input-type=module -e "$SMTP_PROBE_JS" 2>&1 ) && { printf '    %s\n' "$out"; ok "SMTP credentials work"; break; }
    printf '    %s\n' "$out"
    tries=$((tries + 1))
    confirm "SMTP login failed. Re-enter the credentials?" || break
    ask WIZ_SMTP_HOST "SMTP host:"; ask WIZ_SMTP_PORT "SMTP port:"; ask WIZ_SMTP_USER "SMTP user:"
    ask_secret WIZ_SMTP_PASS "SMTP password (hidden):"
    scheme=smtp; [[ $WIZ_SMTP_PORT == 465 ]] && scheme=smtps
    WIZ_SMTP_URL="$scheme://$(urlenc "$WIZ_SMTP_USER"):$(urlenc "$WIZ_SMTP_PASS")@$WIZ_SMTP_HOST:$WIZ_SMTP_PORT"
    unset WIZ_SMTP_PASS
  done
  printf '\n'
  say "Now Supabase Auth → custom SMTP (typed by hand in the dashboard; the password is the same one you just entered):"
  if [[ -n $SUPABASE_REF ]]; then open_url "https://supabase.com/dashboard/project/$SUPABASE_REF/auth/smtp"
  else open_url "https://supabase.com/dashboard"; fi
  step "Authentication → Emails → SMTP Settings → Enable custom SMTP."
  step "Sender email = the verified address in MAIL_FROM; sender name = vCraft."
  step "Host = $WIZ_SMTP_HOST, port = $WIZ_SMTP_PORT, username = $WIZ_SMTP_USER, password = (paste it again). Save."
  pause "Press Enter once Supabase SMTP is saved"
  printf '\n'; say "Setting SMTP_URL and MAIL_FROM on Render vcraft-api and redeploying..."
  if render_env_set SMTP_URL "$WIZ_SMTP_URL" && render_env_set MAIL_FROM "$from" && render_redeploy; then
    if [[ $(sha8 "$WIZ_SMTP_URL") == "$(sha8 "$(render_env_get SMTP_URL)")" ]]; then
      ok "Render SMTP_URL fingerprint matches what you entered ($(sha8 "$WIZ_SMTP_URL"))"; st=0
    else
      bad "Render SMTP_URL differs from the value you entered"
    fi
  fi
  unset WIZ_SMTP_URL
  note "Real test: sign up on $(site_origin) with a real inbox; the confirmation mail must arrive. Notification"
  note "mail from the worker shows in the Render logs (search 'mail')."
  finish_stage s5 "$st"
  return 0
}

# ===========================================================================
# Stage 6: FIELD_ENCRYPTION_KEYS
# ===========================================================================
copy_to_clipboard() {  # copy_to_clipboard VALUE: 0 if a clipboard tool took it
  if command -v pbcopy >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v wl-copy >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v xclip >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  elif command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe
  else return 1; fi
}
stage_field_key() {
  begin s6 "Field encryption key: match and back up" "Kiểm tra khóa mã hóa trên Render khớp .env và lưu bản sao vào trình quản lý mật khẩu." || return 0
  say "Why: citizen ID numbers in the database are AES-256-GCM encrypted. Lose this key and they are"
  say "unrecoverable; if Render's copy differs from the one that encrypted the demo data, reads fail."
  printf '\n'
  local local_key render_key st=1
  local_key=$(envv FIELD_ENCRYPTION_KEYS || true)
  render_key=$(render_env_get FIELD_ENCRYPTION_KEYS || true)
  if [[ -z $local_key ]]; then bad "FIELD_ENCRYPTION_KEYS is missing from $ENV_FILE"
  elif [[ -z $render_key ]]; then bad "FIELD_ENCRYPTION_KEYS is not set on Render vcraft-api"
  else
    if [[ $local_key =~ ^v[0-9]+:[A-Za-z0-9+/]{43}=(,v[0-9]+:[A-Za-z0-9+/]{43}=)*$ ]]; then ok "format is valid (keyId:base64 of 32 bytes)"
    else warn "format does not look like v1:<44 base64 chars> (ADR-18)"; fi
    printf '    .env fingerprint    %s\n    Render fingerprint  %s\n' "$(sha8 "$local_key")" "$(sha8 "$render_key")"
    if [[ $local_key == "$render_key" ]]; then ok "fingerprints match"; st=0; else bad "fingerprints DIFFER: do not deploy until fixed"; fi
  fi
  if (( st == 0 )); then
    printf '\n'; say "Store a copy in your password manager (1Password, Bitwarden, ...):"
    step "New item → name 'vCraft FIELD_ENCRYPTION_KEYS' → password field."
    step "Value = the text after FIELD_ENCRYPTION_KEYS= on its line in $ENV_FILE,"
    step "up to (not including) the spaces and '#' comment. The wizard never prints it."
    if confirm "Copy the key to the clipboard so you can paste it (cleared afterwards)?"; then
      if copy_to_clipboard "$local_key"; then
        ok "copied"; pause "Paste it into the password manager, then press Enter to clear the clipboard"
        copy_to_clipboard "" || true
      else warn "no clipboard tool found: copy it from $ENV_FILE by hand"; fi
    fi
    confirm "The key is saved in a password manager?" || st=1
  fi
  unset local_key render_key
  finish_stage s6 "$st"
  return 0
}

# ===========================================================================
# Stage 7: rotate the leaked Supabase Storage S3 key
# ===========================================================================
stage_s3_rotate() {
  begin s7 "Rotate the leaked Storage S3 key" "Xoay khóa S3 của Supabase Storage đã bị lộ: tạo khóa mới, cập nhật, kiểm tra, rồi mới thu hồi khóa cũ." || return 0
  say "Order matters: create new → verify → update .env and Render → redeploy → verify → ONLY THEN revoke the old key."
  printf '\n'
  local st=1 bak old_ak old_sk new_ak new_sk s3page rk
  if [[ -n $SUPABASE_REF ]]; then s3page="https://supabase.com/dashboard/project/$SUPABASE_REF/storage/s3"; else s3page="https://supabase.com/dashboard"; fi
  if ! state_has s7a; then
    open_url "$s3page"
    step "Storage → S3 Configuration (left sidebar) → Access keys → New access key."
    step "Description 'vcraft-api $(date +%Y-%m)' → Create. Copy the Access key ID and the Secret (shown once)."
    while :; do
      ask_secret NEW_S3_ACCESS_KEY "New Access key ID (hidden):"
      ask_secret NEW_S3_SECRET_KEY "New Secret access key (hidden):"
      new_ak=$NEW_S3_ACCESS_KEY; new_sk=$NEW_S3_SECRET_KEY
      unset NEW_S3_ACCESS_KEY NEW_S3_SECRET_KEY
      if [[ $new_ak == "$(envv S3_ACCESS_KEY || true)" ]]; then warn "that is the OLD key; create a new one"; continue; fi
      say "Testing the new key against Supabase Storage..."
      if s3_probe "$new_ak" "$new_sk"; then ok "new key works on both buckets"; break; fi
      confirm "The new key failed. Try entering it again?" || { unset new_ak new_sk; finish_stage s7 1; return 0; }
    done
    bak="$ENV_FILE.bak-$(date +%Y%m%d-%H%M%S)"
    (umask 077; cp -p "$ENV_FILE" "$bak"); chmod 600 "$bak"
    state_set S3_BACKUP "$bak"
    ok "backed up the current .env to $bak (contains the OLD key; delete it at the end)"
    write_env S3_ACCESS_KEY "$new_ak"; write_env S3_SECRET_KEY "$new_sk"; chmod 600 "$ENV_FILE"
    say "Updating Render and redeploying..."
    if render_env_set S3_ACCESS_KEY "$new_ak" && render_env_set S3_SECRET_KEY "$new_sk" && render_redeploy; then
      if [[ $(sha8 "$new_sk") == "$(sha8 "$(render_env_get S3_SECRET_KEY)")" ]]; then
        ok "Render secret fingerprint matches ($(sha8 "$new_sk"))"; state_add s7a
      else bad "Render's S3_SECRET_KEY differs from the new key"; fi
    fi
    unset new_ak new_sk
  fi
  if state_has s7a; then
    bak=$(state_get S3_BACKUP)
    old_ak=""; old_sk=""
    if [[ -f $bak ]]; then old_ak=$(env_val "$bak" S3_ACCESS_KEY || true); old_sk=$(env_val "$bak" S3_SECRET_KEY || true); fi
    printf '\n'; say "New key is live everywhere. Now revoke the OLD one."
    open_url "$s3page"
    step "Storage → S3 Configuration → Access keys: delete the OLD key (its ID starts with '${old_ak:0:4}...')."
    step "Do NOT delete the new one."
    pause "Press Enter once the old key is deleted"
    say "Re-verifying..."
    new_ak=$(envv S3_ACCESS_KEY); new_sk=$(envv S3_SECRET_KEY)
    if s3_probe "$new_ak" "$new_sk"; then ok "new key still works"; st=0; else bad "new key stopped working: did you delete the wrong key?"; fi
    unset new_ak new_sk
    if [[ -n $old_ak && -n $old_sk ]]; then
      if s3_probe "$old_ak" "$old_sk" >/dev/null 2>&1; then bad "OLD key still works: it is not revoked yet"; st=1
      else ok "old key is rejected"; fi
    else warn "old key not found in the backup: skipping the revoked-check"; fi
    unset old_ak old_sk
    rk=$(render_env_get S3_ACCESS_KEY || true)
    [[ -n $rk ]] && note "Render access key id fingerprint: $(sha8 "$rk")"
    unset rk
    if (( st == 0 )) && [[ -f $bak ]] && confirm "Delete the .env backup ($bak)? It still holds the old secret and every other .env value."; then
      rm -f "$bak"; ok "backup deleted"
    fi
  fi
  finish_stage s7 "$st"
  return 0
}

# ===========================================================================
# Stage 8: NEXT_PUBLIC_PRIVACY_EMAIL
# ===========================================================================
stage_privacy_email() {
  begin s8 "Privacy contact mailbox" "Đặt hộp thư nhận yêu cầu dữ liệu cá nhân, hiện ở trang chính sách quyền riêng tư." || return 0
  say "Why: the privacy policy shows a mailto link for personal-data requests (NFR-SEC-07). Unset, the page"
  say "falls back to generic wording. It is a build-time variable, so the web is redeployed."
  printf '\n'
  local st=1 email origin i
  origin=$(site_origin)
  step "Use a mailbox you actually read (e.g. privacy@yourdomain.vn or a shared Gmail)."
  while :; do
    ask WIZ_PRIVACY_EMAIL "Privacy mailbox address:"
    if [[ $WIZ_PRIVACY_EMAIL =~ ^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$ ]]; then break; fi
    warn "that is not a valid email address"
  done
  email=$WIZ_PRIVACY_EMAIL
  if vercel_env_set NEXT_PUBLIC_PRIVACY_EMAIL "$email"; then
    write_env NEXT_PUBLIC_PRIVACY_EMAIL "$email"
    if deploy_web; then
      for ((i = 0; i < 6; i++)); do
        if curl -fsS -m 30 "$origin/vi/chinh-sach-quyen-rieng-tu" 2>/dev/null | grep -qF "mailto:$email"; then
          ok "privacy page at $origin links mailto:$email"; st=0; break
        fi
        note "mailto not visible yet, retrying in 10s..."; sleep 10
      done
      (( st == 0 )) || bad "the privacy page does not contain mailto:$email"
    fi
  fi
  finish_stage s8 "$st"
  return 0
}

# ===========================================================================
# Stage 9: release verification (GH#39 / GH#40)
# ===========================================================================
run_check() {  # run_check "label" command...: prints PASS/FAIL, counts failures
  local label=$1; shift
  if "$@" >/dev/null 2>&1; then ok "$label"; return 0; fi
  bad "$label"; CHECK_FAILS=$((CHECK_FAILS + 1)); return 0
}
c_health()  { curl -fsS -m 60 "$1/api/v1/health" | jq -e '.status == "ok"'; }
c_qr308()   { [[ $(curl -s -o /dev/null -m 30 -w '%{http_code} %{redirect_url}' "$1/q/DF6P3WZE") == "308 $1/vi/truy-xuat/DF6P3WZE" ]]; }
c_header()  { local h; h=$(curl -s -m 30 -D - -o /dev/null "$1/vi"); grep -qi "^$2:" <<<"$h"; }   # GET, not HEAD
c_news()    { [[ $(curl -fsS -m 60 "$1/vi/tin-tuc" | grep -oE 'href="/vi/tin-tuc/[^"]+"' | sort -u | wc -l) -ge 3 ]]; }
c_awake()   { [[ $(curl -fsS -m 30 -o /dev/null -w '%{time_total}' "$API_ORIGIN/api/v1/health" | awk '{print ($1 < 3) ? 1 : 0}') == 1 ]]; }
c_ci() {  # latest CI run on main: the integration matrix (postgresql + mysql) must be green
  local run
  run=$(gh run list -R "$REPO_SLUG" --workflow ci.yml --branch main --limit 1 --json databaseId -q '.[0].databaseId')
  [[ -n $run ]] || return 1
  gh run view "$run" -R "$REPO_SLUG" --json jobs -q '[.jobs[] | select(.name | test("integration")) | .conclusion] | (length >= 2) and all(. == "success")' | grep -qx true
}
run_suite() {  # run_suite "label" command...: runs in the repo with E2E_BASE_URL, reports exit status
  local label=$1; shift
  say "running: $label"
  if "$@"; then ok "$label passed"; return 0; fi
  bad "$label failed"; CHECK_FAILS=$((CHECK_FAILS + 1)); return 0
}
stage_verify() {
  begin s9 "Release verification on production" "Kiểm thử phát hành (GH#39, GH#40): script tự chạy phần kiểm được, phần còn lại bạn xác nhận." || return 0
  local origin st=1 manual_ok=1
  origin=$(site_origin); CHECK_FAILS=0
  say "Target: $origin   (GH#40: release verification; GH#39 acceptance spot-checks)"
  printf '\n'; say "Automated checks"
  run_check "API health through the Vercel rewrite ($origin/api/v1/health)" c_health "$origin"
  run_check "API health direct ($API_ORIGIN)" c_health "$API_ORIGIN"
  run_check "/q/DF6P3WZE → 308 → /vi/truy-xuat/DF6P3WZE" c_qr308 "$origin"
  run_check "HSTS header on GET $origin/vi" c_header "$origin" strict-transport-security
  run_check "CSP header on GET $origin/vi" c_header "$origin" content-security-policy
  run_check "/vi/tin-tuc lists articles (server-side fetch from the API works)" c_news "$origin"
  run_check "API answers in under 3 s (no cold start)" c_awake
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    run_check "CI on main: integration matrix green on PostgreSQL and MySQL" c_ci
  else
    warn "gh not available: check by hand that the 'integration' jobs (postgresql, mysql) are green on main"
  fi
  printf '\n'; say "Optional automated suites (need Playwright browsers; DEMO_* passwords from .env)"
  if confirm "Run read-only data checks (pnpm demo:verify, pnpm demo:auth -- --check) against the .env database?"; then
    run_suite "pnpm demo:verify" pnpm demo:verify
    run_suite "pnpm demo:auth -- --check" pnpm demo:auth -- --check
  fi
  if confirm "Run pnpm demo:e2e:preexam against $origin (WCAG, responsive, keyboard; a few minutes)?"; then
    run_suite "pnpm demo:e2e:preexam" env E2E_BASE_URL="$origin" pnpm demo:e2e:preexam
    note "If browsers are missing: pnpm --filter @vcraft/e2e exec playwright install chromium"
  fi
  warn "pnpm demo:e2e (QR → receipt) MUTATES the frozen data and needs pnpm demo:reset before and after."
  warn "demo:reset deletes data: it needs APP_ENV=demo and DEMO_RESET_CONFIRM typed by you; the wizard never runs it."
  if confirm "You just ran pnpm demo:reset yourself and want to run pnpm demo:e2e now?"; then
    run_suite "pnpm demo:e2e" env E2E_BASE_URL="$origin" pnpm demo:e2e
    warn "Now run pnpm demo:reset again to restore the frozen data."
    pause "Press Enter once you have reset the data"
  else
    SKIPPED+=("pnpm demo:reset && E2E_BASE_URL=$origin pnpm demo:e2e && pnpm demo:reset  (GH#40: QR → receipt)")
  fi
  printf '\n'; say "Manual checks (answer honestly; these are the GH#40 acceptance items)"
  confirm "A QR label printed on a real ceramic cup opened the trace page on a phone over 4G, in under 3 s?" || manual_ok=0
  confirm "Three browser profiles are signed in: buyer (Chrome), household (phone), admin (Edge)?" || manual_ok=0
  confirm "Sign-up and password-reset emails arrive and link back to $origin?" || manual_ok=0
  if confirm "Take the database + storage backup now (data must be frozen)?"; then
    take_backup || manual_ok=0
  else
    manual_ok=0; SKIPPED+=("Backup of Supabase database + storage after the data freeze (docs/demo/README.md section 6)")
  fi
  if (( CHECK_FAILS == 0 && manual_ok == 1 )); then st=0; fi
  if (( CHECK_FAILS )); then bad "$CHECK_FAILS automated check(s) failed"; fi
  finish_stage s9 "$st"
  return 0
}
take_backup() {  # DB dump with pg_dump and S3 sync with aws cli, into $BACKUP_DIR (outside the repo)
  local ts dumped=1 synced=1 ca
  ts=$(date +%Y%m%d-%H%M)
  mkdir -p "$BACKUP_DIR"; chmod 700 "$BACKUP_DIR"
  if command -v pg_dump >/dev/null 2>&1; then
    ca=$(envv DB_SSL_CA_FILE || true)
    if (
      export PGPASSWORD; PGPASSWORD=$(envv DB_PASSWORD)
      pg_dump "postgresql://$(urlenc "$(envv DB_USER)")@$(envv DB_HOST):$(envv DB_PORT)/$(envv DB_NAME)?sslmode=verify-full&sslrootcert=${ca:-system}" \
        --format=custom --no-owner --no-privileges --schema=public --file="$BACKUP_DIR/vcraft-$ts.dump"
    ); then ok "database dump: $BACKUP_DIR/vcraft-$ts.dump"; dumped=0; else bad "pg_dump failed"; fi
  else warn "pg_dump not installed: see docs/demo/README.md section 6"; fi
  if command -v aws >/dev/null 2>&1; then
    if (
      export AWS_ACCESS_KEY_ID AWS_SECRET_ACCESS_KEY
      AWS_ACCESS_KEY_ID=$(envv S3_ACCESS_KEY); AWS_SECRET_ACCESS_KEY=$(envv S3_SECRET_KEY)
      aws s3 sync "s3://$(envv S3_BUCKET_PUBLIC)" "$BACKUP_DIR/media-$ts" --endpoint-url "$(envv S3_ENDPOINT)" --region "$(envv S3_REGION)" --only-show-errors
    ); then ok "storage copy: $BACKUP_DIR/media-$ts"; synced=0; else bad "aws s3 sync failed"; fi
  else warn "aws CLI not installed: copy the vcraft-media / vcraft-private buckets another way"; fi
  if (( dumped == 0 && synced == 0 )); then return 0; fi
  confirm "Did you take the database and storage backup by another route?"
}

# ===========================================================================
# Orchestration
# ===========================================================================
print_status() {
  local id title
  for id in s1 s2 s3 s4 s5 s6 s7 s8 s9; do
    case $id in
      s1) title="Connect Vercel to GitHub" ;;      s2) title="Render paid plan (optional)" ;;
      s3) title="Custom domain (optional)" ;;      s4) title="Supabase Auth URLs" ;;
      s5) title="SMTP" ;;                          s6) title="Field encryption key" ;;
      s7) title="Rotate the S3 key" ;;             s8) title="Privacy mailbox" ;;
      s9) title="Release verification" ;;
    esac
    if state_has "done:$id"; then printf '  %s✓%s %s  %s\n' "$GREEN" "$RESET" "$id" "$title"
    elif state_has "skip:$id"; then printf '  %s-%s %s  %s (skipped on purpose)\n' "$YELLOW" "$RESET" "$id" "$title"
    else printf '  %s·%s %s  %s\n' "$DIM" "$RESET" "$id" "$title"; fi
  done
  printf '\n  state file: %s\n' "$STATE_FILE"
}

usage() {
  cat <<EOF
vCraft release wizard: the release steps only a human can do.

  scripts/release-wizard.sh              run (finished steps are skipped)
  scripts/release-wizard.sh --status     show which steps are done
  scripts/release-wizard.sh --reset ID   forget step ID (s1..s9) so it runs again
  scripts/release-wizard.sh --reset all  forget everything

Env: ENV_FILE (default <repo>/.env), WIZARD_STATE_FILE, VERCEL_TOKEN, RENDER_API_KEY.
EOF
}

run_wizard() {

ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
cd "$ROOT"
TOTAL_STAGES=9

case "${1:-}" in
  -h|--help) usage; return 0 ;;
  --status) print_status; return 0 ;;
  --reset)
    case "${2:-}" in
      all) rm -f "$STATE_FILE"; echo "state cleared"; return 0 ;;
      s[1-9]) state_del "done:$2"; state_del "skip:$2"; [[ $2 == s7 ]] && state_del s7a; echo "stage $2 will run again"; return 0 ;;
      *) usage; return 1 ;;
    esac ;;
  "") ;;
  *) usage; return 1 ;;
esac

preflight

banner "vCraft release wizard"

stage_vercel_github
stage_render_paid
stage_domain
stage_supabase_auth
stage_smtp
stage_field_key
stage_s3_rotate
stage_privacy_email
stage_verify

finish
print_status
if (( HAS_FAILURE )); then note "Some stages are still open: run this wizard again after fixing them."; fi
}

run_wizard "$@"; exit
